WITH filtered AS (SELECT *, UPPER(channel) AS channel_upper, COALESCE(channel, 'OTHER') AS channel_clean FROM orders WHERE order_date > TO_DATE('2023-04-05') AND channel IS NOT NULL) SELECT d.region, a.channel, COUNT(*) AS num_rows, ROUND(SUM(a.amount), 2) AS total_amount, GROUPING_ID() AS gid FROM filtered a LEFT JOIN stores d ON a.store_id = d.id GROUP BY CUBE (d.region, a.channel);
